begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id) values ('30000000-0000-0000-0000-000000000003'),('40000000-0000-0000-0000-000000000004');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
select throws_ok($$select * from private.ai_jobs$$,'42501',null,'Client cannot read sensitive job payloads');
select ok(not has_function_privilege('authenticated','public.ai_get_dream_job(uuid,uuid)','EXECUTE'),'Client cannot call internal resume RPC');
select ok(not has_function_privilege('authenticated','public.ai_prune_jobs()','EXECUTE'),'Client cannot prune jobs');
select throws_ok($$update public.dreams set analysis_source='live'$$,'42501',null,'Client cannot forge AI provenance');
select throws_ok($$update public.dreams set ai_processing_consent_at=now()$$,'42501',null,'Client cannot forge processing receipt');
reset role;
insert into private.ai_daily_budget(day,reserved_micros) values((now() at time zone 'UTC')::date,0) on conflict(day) do update set reserved_micros=0;
select lives_ok($$select public.ai_reserve_job('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003',repeat('a',64),'{"transcript":"Synthetic dream","inputMode":"text","dreamDate":"2026-10-11","timezone":"UTC","locale":"tr","processingConsent":true}',1,2000000)$$,'Reservation creates a durable private job');
select is((select status from public.dreams where id='31000000-0000-0000-0000-000000000003'),'processing','Reserved dream has processing status');
select ok((select not aggregate_opt_in and not matching_opt_in from public.dreams where id='31000000-0000-0000-0000-000000000003'),'AI processing never grants social consent');
select lives_ok($$select public.ai_reserve_job('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003',repeat('a',64),'{}',1,2000000)$$,'Identical receipt retry does not reserve again');
select is((select reserved_micros from private.ai_daily_budget where day=(now() at time zone 'UTC')::date),100000::bigint,'Idempotent retry consumes one budget reservation');
select throws_ok($$select public.ai_reserve_job('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003',repeat('b',64),'{}',1,2000000)$$,'P0001','IDEMPOTENCY_CONFLICT','Changed content cannot reuse a receipt');
select throws_ok($$select public.ai_reserve_job('30000000-0000-0000-0000-000000000003','32000000-0000-0000-0000-000000000003','32000000-0000-0000-0000-000000000003',repeat('a',64),'{}',1,2000000)$$,'P0001','RATE_LIMITED','Per-user quota enforced before providers');
select throws_ok($$select public.ai_reserve_job('40000000-0000-0000-0000-000000000004','41000000-0000-0000-0000-000000000004','41000000-0000-0000-0000-000000000004',repeat('a',64),'{}',3,100000)$$,'P0001','BUDGET_EXCEEDED','Global reservation budget enforced atomically');
select is(public.ai_get_job('40000000-0000-0000-0000-000000000004','31000000-0000-0000-0000-000000000003'),null::jsonb,'Internal retrieval still checks ownership');
select is(public.ai_attempt('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','interpret'),1,'First GPT attempt recorded');
select is(public.ai_attempt('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','interpret'),2,'One retry allowed');
select throws_ok($$select public.ai_attempt('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','interpret')$$,'P0001','ATTEMPTS_EXHAUSTED','Third paid GPT call denied');
select is(public.ai_attempt('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','image'),1,'One image attempt allowed');
select throws_ok($$select public.ai_attempt('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','image')$$,'P0001','ATTEMPTS_EXHAUSTED','Repeated paid image call denied');
select public.ai_patch_job('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','{"transcript":"Synthetic dream","audioPath":"private/path.m4a"}');
select lives_ok($$select public.save_ai_dream('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','{"transcript":"Synthetic dream","inputMode":"text","dreamDate":"2026-10-11","timezone":"UTC","locale":"tr","analysisSource":"live","astrologyContext":{"available":true}}','{"image_prompt":"Anonymous ocean","interpretations":{"neuroscience":"Synthetic interpretation","jungian":"Synthetic interpretation","astrological":"Synthetic interpretation"},"tags":["water","home","silence"]}','30000000-0000-0000-0000-000000000003/31000000-0000-0000-0000-000000000003/image.png',null)$$,'AI save and receipt completion commit together');
select ok((select status='ready' and analysis_source='live' and ai_processing_consent_at is not null from public.dreams where id='31000000-0000-0000-0000-000000000003'),'Ready dream retains provenance and consent timestamp');
select ok((select status='completed' and input='{}' and state='{"completed":true}' from private.ai_jobs where id='31000000-0000-0000-0000-000000000003'),'Completion removes duplicated sensitive job content');
select public.ai_finish_job('30000000-0000-0000-0000-000000000003','31000000-0000-0000-0000-000000000003','LOST_RESPONSE');
select is((select status from public.dreams where id='31000000-0000-0000-0000-000000000003'),'ready','Lost response cannot downgrade a committed dream');
delete from auth.users where id='30000000-0000-0000-0000-000000000003';
select is((select count(*)::int from private.ai_jobs where user_id='30000000-0000-0000-0000-000000000003'),0,'Account deletion cascades through private jobs');
select is((select count(*)::int from private.ai_user_usage where user_id='30000000-0000-0000-0000-000000000003'),0,'Account deletion removes user rate counters');
select * from finish();
rollback;
